const markOwnNotificationRead = `-- name: MarkOwnNotificationRead :execrows
UPDATE inbox_recipients
SET read_at = COALESCE(read_at, $1)
WHERE notification_id = $2 AND account_id = $3
`

type MarkOwnNotificationReadParams struct {
	Now            pgtype.Timestamptz
	NotificationID uuid.UUID
	AccountID      uuid.UUID
}

// Idempotent: an already read notification keeps its first read time but still counts as found.
func (q *Queries) MarkOwnNotificationRead(ctx context.Context, arg MarkOwnNotificationReadParams) (int64, error) {
	result, err := q.db.Exec(ctx, markOwnNotificationRead, arg.Now, arg.NotificationID, arg.AccountID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

